<?php
namespace App\Http\Controllers\Client;
use App\Http\Controllers\Controller;use App\Models\Service;use App\Services\Pterodactyl\PterodactylClient;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Validation\ValidationException;use Throwable;
class ClientServerUserController extends Controller{public function index(Request $request,Service $service,PterodactylClient $client):JsonResponse{$id=$this->identifier($request,$service);try{$r=$client->listServerUsers($id);$p=$client->listClientPermissions();$users=collect(data_get($r,'data',[]))->map(function($x){$a=(array)data_get($x,'attributes',[]);return ['uuid'=>(string)data_get($a,'uuid'),'username'=>(string)data_get($a,'username'),'email'=>(string)data_get($a,'email'),'image'=>(string)data_get($a,'image'),'two_factor'=>(bool)data_get($a,'2fa_enabled',false),'permissions'=>array_values((array)data_get($a,'permissions',[]))];})->values();$groups=collect((array)data_get($p,'attributes.permissions',data_get($p,'permissions',[])))->map(function($g,$key){$g=(array)$g;return ['key'=>(string)$key,'description'=>(string)data_get($g,'description',''),'permissions'=>collect((array)data_get($g,'keys',[]))->map(fn($d,$k)=>['key'=>$key.'.'.$k,'description'=>(string)$d])->values()];})->values();return response()->json(['users'=>$users,'permission_groups'=>$groups]);}catch(Throwable $e){report($e);return response()->json(['message'=>'Impossible de charger les utilisateurs.'],502);}}public function store(Request $request,Service $service,PterodactylClient $client):JsonResponse{$id=$this->identifier($request,$service);$v=$request->validate(['email'=>['required','email','max:255'],'permissions'=>['required','array','max:100'],'permissions.*'=>['string','max:100']]);try{$client->createServerUser($id,$v['email'],$v['permissions']);return response()->json(['message'=>'Utilisateur invité.'],201);}catch(Throwable $e){report($e);return response()->json(['message'=>'Impossible d’inviter cet utilisateur.'],502);}}public function update(Request $request,Service $service,string $user,PterodactylClient $client):JsonResponse{$id=$this->identifier($request,$service);$v=$request->validate(['permissions'=>['required','array','max:100'],'permissions.*'=>['string','max:100']]);try{$client->updateServerUser($id,$user,$v['permissions']);return response()->json(['message'=>'Permissions mises à jour.']);}catch(Throwable $e){report($e);return response()->json(['message'=>'Impossible de modifier les permissions.'],502);}}public function destroy(Request $request,Service $service,string $user,PterodactylClient $client):JsonResponse{$id=$this->identifier($request,$service);try{$client->deleteServerUser($id,$user);return response()->json(['message'=>'Accès supprimé.']);}catch(Throwable $e){report($e);return response()->json(['message'=>'Impossible de supprimer cet accès.'],502);}}    private function identifier(Request $request, Service $service): string { abort_unless((int)$service->user_id === (int)$request->user()->id,403); $identifier=(string)data_get($service->configuration,'pterodactyl.identifier'); if($identifier===''){ throw ValidationException::withMessages(['service'=>'Identifiant Pterodactyl introuvable.']); } return $identifier; }}
